// Obtém a lista bruta de artigos retornados pela API
const rawHits = $input.first().json.hits || [];

// 1. Filtra itens com título e URL válidos
// 2. Ordena pelos mais votados (pontos)
// 3. Seleciona os 5 mais relevantes
const topStories = rawHits
  .filter(item => item.title && (item.url || item.story_url))
  .sort((a, b) => (b.points || 0) - (a.points || 0))
  .slice(0, 5)
  .map(item => ({
    titulo: item.title,
    pontos: item.points || 0,
    autor: item.author,
    link: item.url || item.story_url,
    data_publicacao: item.created_at
  }));

// Retorna cada notícia como um item individual estruturado no padrão do n8n
return topStories.map(story => ({ json: story }));

