// Obtém todos os itens processados pelo Gemini
const items = $input.all();

// Data formatada para o cabeçalho do briefing
const hoje = new Date().toLocaleDateString('pt-BR', {
  day: '2-digit',
  month: '2-digit',
  year: 'numeric'
});

// Cabeçalho do relatório
let briefingMarkdown = `# 🛰️ RADAR DE INTELIGÊNCIA DE MERCADO & IA\n`;
briefingMarkdown += `**Data da Edição:** ${hoje} | **Curadoria:** Hacker News Top Stories\n\n`;
briefingMarkdown += `---\n\n`;

// Itera sobre as análises geradas pelo Gemini e concatena no documento final
items.forEach((item, index) => {
  // Captura o texto gerado pelo Gemini
  const analise = item.json.content?.parts?.[0]?.text || item.json.text || item.json.output || JSON.stringify(item.json);

  briefingMarkdown += `### Item ${index + 1}\n`;
  briefingMarkdown += `${analise}\n\n`;
  briefingMarkdown += `---\n\n`;
});

// Retorna um único objeto JSON contendo o relatório completo compilado
return [
  {
    json: {
      relatorio_final: briefingMarkdown,
      total_itens: items.length,
      data_extracao: hoje
    }
  }
];
